        `MACRO_DIR=$(srcdir)/$$(cd $(top_srcdir); $(AUTOCONF) --trace 'AC_CONFIG_MACRO_DIR:$$1' ./configure.ac); \
         if test "x$$MACRO_DIR" != "x$(srcdir)/"; then \
